// Tensor-product cubic B-spline, including polynomial extrapolation.
template <std::size_t N>
double cubic(double x, const std::array<double, N + 4> &t,
             const std::array<double, N> &coefficients) {
  int span = 3;
  while (span < static_cast<int>(N) - 1 &&
         x >= t[static_cast<std::size_t>(span + 1)])
    ++span;
  std::array<double, 4> d{};
  for (int j = 0; j < 4; ++j)
    d[static_cast<std::size_t>(j)] =
        coefficients[static_cast<std::size_t>(span - 3 + j)];
  for (int r = 1; r <= 3; ++r)
    for (int j = 3; j >= r; --j) {
      const auto i = static_cast<std::size_t>(span - 3 + j);
      const double alpha =
          (x - t[i]) / (t[i + static_cast<std::size_t>(4 - r)] - t[i]);
      d[static_cast<std::size_t>(j)] =
          (1. - alpha) * d[static_cast<std::size_t>(j - 1)] +
          alpha * d[static_cast<std::size_t>(j)];
    }
  return d[3];
}
