double pressure_Zhao_1997_hBN(double volume, double temperature,
                              const Params &params) {
  const double a0 = params.at("a0");
  const double a1 = params.at("a1");
  const double K0 = params.at("K_0");
  const double Kprime0 = params.at("Kprime_0");
  const double dK_dT = params.at("dK_dT");
  const double dKprime_dT = params.at("dKprime_dT");
  const double KT = (K0 + (dK_dT * (temperature - 300.0)));
  const double KprimeT = (Kprime0 + (dKprime_dT * (temperature - 300.0)));
  const double V0T =
      (params.at("V_0") *
       std::exp(
           (((a0 * temperature) + (a1 * (std::pow(temperature, 2.0) / 2.0))) -
            ((a0 * 300.0) + (a1 * (std::pow(300.0, 2.0) / 2.0))))));
  const double V_V0T = (volume / V0T);
  const double f = (0.5 * (std::pow(V_V0T, ((-2.0) / 3.0)) - 1.0));
  const double P =
      ((((3.0 * KT) * f) * std::pow((1.0 + (2.0 * f)), (5.0 / 2.0))) *
       (1.0 - (((3.0 / 2.0) * (4.0 - KprimeT)) * f)));
  return P;
}

